using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Launch;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public sealed class RivalsPlayerProbe:MonoBehaviour {
 static string folder;readonly List<string> checks=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--rivals-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=folder+"/isolated-v7.json";}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var g=new GameObject("Rivals native verification");DontDestroyOnLoad(g);g.AddComponent<RivalsPlayerProbe>();}
 void Check(bool yes,string text){checks.Add((yes?"PASS ":"FAIL ")+text);File.WriteAllLines(folder+"/results.txt",checks);if(!yes){failed=true;Application.Quit(1);throw new Exception(text);}}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string t,string stack,LogType type){if(!failed&&(type==LogType.Error||type==LogType.Exception))Check(false,"Runtime error: "+t);}void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Native rivals timeout");}
 IEnumerator Wait(Func<bool> ready){while(!ready())yield return null;yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.3f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(folder+"/"+name+".png");yield return new WaitForSecondsRealtime(.4f);Check(new FileInfo(folder+"/"+name+".png").Length>50000,"Actual rendered screen: "+name);}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+240;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>RivalRaceDirector.Instance?.Ready==true);var d=RivalRaceDirector.Instance;var car=d.Trial.vehicle;car.externalInput=true;car.commandedPedal=0;car.commandedHandbrake=false;car.commandedServiceBrake=1;var traffic=FindAnyObjectByType<TrafficWorld>();yield return new WaitForSecondsRealtime(13);Check(traffic.Spawned>=6,"Regular traffic spawns multiple physical AI cars around player");Check(TrafficWorld.Agents.Where(a=>!a.IsRival).All(a=>a.Car.Wheels.Length==4&&!a.Car.Body.isKinematic),"Traffic uses dynamic collisions and four physical tires");Check(TrafficWorld.Agents.Any(a=>a.DistanceMoved>10),"Traffic actually travels along its road routes");Screen.SetResolution(1400,800,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.4f);Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);yield return Capture("City_Traffic");car.ResetAt(car.transform.position,car.transform.rotation);Check(d.OpenPanel(),"Rivals and fleet panel opens while stopped");yield return Capture("Rivals_Fleet_1280x720");if(Array.IndexOf(Environment.GetCommandLineArgs(),"--rivals-ui-only")>=0){Check(true,"Final UI layout reviewed without changing gameplay");Application.Quit(0);yield break;}d.Pinks=true;d.StakeConfirmed=false;Check(!d.StartRace()&&!d.Trial.Store.Profile.fleet.HasPending,"Unconfirmed pink slip cannot commit stakes");d.Pinks=false;int initial=d.Trial.Store.Profile.availableCredits;Check(d.StartRace(),"Cash race starts with persisted opponent and frozen terms: "+d.Message);Check(d.Opponent.Car.Engine.definition.PeakKw()>0&&d.Opponent.Car.GetComponentsInChildren<WheelCollider>().Length==4,"Rival is a real drivable physics car with authored powertrain");Check(!FindAnyObjectByType<ExpandedWorkshop>().Open(),"Garage cannot open while rival race owns controls");yield return Capture("Rival_Countdown");var pilot=car.gameObject.AddComponent<RoadPilot>();pilot.Car=car;pilot.Path=d.Trial.Definition.route.Select(p=>p.Position).ToArray();pilot.CruiseKph=85;pilot.IsRival=true;pilot.Lane=-1.7f;pilot.Held=true;Time.timeScale=4;int last=0;double stalled=Time.realtimeSinceStartupAsDouble;bool image=false;var tap=Camera.main.gameObject.AddComponent<TurboNativeAudioTap>();tap.Begin();while(!d.Results&&!d.SavePending){pilot.Held=d.Race.Player.State==TrialState.Countdown;if(last!=d.Race.Player.NextGate){last=d.Race.Player.NextGate;stalled=Time.realtimeSinceStartupAsDouble;}if(Time.realtimeSinceStartupAsDouble-stalled>15&&d.Race.Player.State==TrialState.Running){d.TryRecover(car);pilot.RecoverAt(d.Trial.Definition.checkpoints[Math.Max(0,d.Race.Player.NextGate-1)]);stalled=Time.realtimeSinceStartupAsDouble;}if(!image&&d.Race.Player.NextGate>=6){image=true;yield return Capture("AI_Race_On_Road");}yield return null;}Time.timeScale=1;Destroy(pilot);Check(d.Results&&!d.SavePending&&d.Race.Player.ValidFinish,"Native physical full-lap race resolves after player's valid finish");var finished=d.Race;Check(d.Trial.Store.Profile.availableCredits>initial,"Real race grants additional saved profit");int paid=d.Trial.Store.Profile.availableCredits;d.Trial.Store.SettleDuel(finished);Check(d.Trial.Store.Profile.availableCredits==paid,"Native result retry cannot pay twice");Check(tap.Finish(folder+"/Actual_Rivals_Mix.wav")>10000,"Actual player/traffic/rival listener mix recorded");Destroy(tap);yield return Capture("Cash_Result");yield return Wait(()=>car.SpeedKph<2);d.ReturnToRoad();Check(d.OpenPanel(),"Stopped player can reopen rivals after result");d.Pinks=true;d.StakeConfirmed=true;Check(d.StartRace(),"Explicit pink-slip agreement commits named owned car");string original=d.Race.Contract.playerId;Check(d.BeforeLeave(),"Deliberate abandon settles confirmed pink-slip forfeit");Check(FleetLedger.Find(d.Trial.Store.Profile.fleet,original).owner=="rival"&&d.Trial.Store.Profile.fleet.selectedId==FleetLedger.Loaner,"Last car transfers permanently and recovery loaner is selected");Check(car.displayName.Contains("LOANER")&&car.Engine.definition.PeakKw()==WorkshopCatalog.Load("car_finch").Resolve(new WorkshopBuild()).PeakKw(),"Recovery loaner is actual stock drivable car, not lost upgraded car");yield return Capture("Pink_Loss_Recovery");d.ReturnToRoad();string saved=File.ReadAllText(d.Trial.Store.PathName);Check(new RaceProgressStore(d.Trial.Store.PathName,d.Trial.Definition).Profile.fleet.selectedId==FleetLedger.Loaner,"Native title loss and loaner survive reload");HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene);yield return Wait(()=>!HarborValeLaunch.Instance.Busy);HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);Check(RivalRaceDirector.Instance==null&&FindAnyObjectByType<TrafficWorld>()==null,"Apex sandbox does not create paid rivals or street traffic");Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==saved,"Apex launch leaves owned-car paid ledger byte-identical");Check(!failed,"Native rival/traffic run has no runtime errors");Application.Quit(0);}
}
}
